let editedPriceProduct=null;const finalPrice=(price,discount)=>Math.round(Number(price||0)*(1-Number(discount||0)/100)*100)/100;function updatePricePreview(){if(!editedPriceProduct)return;const base=Number($('priceEditorBase').value),discount=Number($('priceEditorDiscount').value);$('priceTargetFinal').textContent=rub(finalPrice(base,discount));$('priceTargetFormula').textContent=`${num(base)} в‚Ѕ в€’ ${num(discount)}%`;$('priceEditorApply').disabled=!(Number.isInteger(base)&&base>0&&Number.isInteger(discount)&&discount>=0&&discount<=99)}function closePriceEditor(){priceModal.classList.add('hidden')}function openPriceEditor(nmId){editedPriceProduct=repricerRows.find(x=>String(x.nmId)===String(nmId));if(!editedPriceProduct)return;$('priceEditorTitle').textContent=editedPriceProduct.vendorCode||editedPriceProduct.brand||`nmID ${editedPriceProduct.nmId}`;$('priceEditorMeta').textContent=`nmID ${editedPriceProduct.nmId} В· РёР·РјРµРЅРµРЅРёРµ С‚РѕР»СЊРєРѕ СЌС‚РѕРіРѕ С‚РѕРІР°СЂР°`;$('priceCurrentFinal').textContent=rub(editedPriceProduct.discountedPrice);$('priceCurrentFormula').textContent=`${num(editedPriceProduct.price)} в‚Ѕ в€’ ${num(editedPriceProduct.discount)}%`;$('priceEditorBase').value=editedPriceProduct.price;$('priceEditorDiscount').value=editedPriceProduct.discount;$('priceEditorStatus').className='price-status';$('priceEditorStatus').textContent='РР·РјРµРЅРµРЅРёСЏ РµС‰С‘ РЅРµ РѕС‚РїСЂР°РІР»РµРЅС‹ РІ WB.';updatePricePreview();priceModal.classList.remove('hidden')}$('priceEditorClose').onclick=closePriceEditor;$('priceEditorCancel').onclick=closePriceEditor;priceModal.onclick=e=>{if(e.target===priceModal)closePriceEditor()};$('priceEditorBase').oninput=updatePricePreview;$('priceEditorDiscount').oninput=updatePricePreview;
renderPriceGrid=()=>{const q=($('repricerBrand').value||'').toLowerCase(),rows=repricerRows.filter(x=>x.brand.toLowerCase().includes(q));$('repricerStatus').textContent=`${rows.length} С‚РѕРІР°СЂРѕРІ В· РІС‹Р±РµСЂРёС‚Рµ С‚РѕРІР°СЂ`;$('repricerBody').innerHTML=rows.length?`<table class="stock-table"><thead><tr><th>РўРѕРІР°СЂ</th><th>Р‘Р°Р·РѕРІР°СЏ С†РµРЅР°</th><th>РЎРєРёРґРєР° РїСЂРѕРґР°РІС†Р°</th><th>Р¦РµРЅР° РїСЂРѕРґР°РІС†Р° РїРѕСЃР»Рµ СЃРєРёРґРєРё</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.vendorCode||x.brand||`nmID ${x.nmId}`)}</b><small>nmID ${esc(x.nmId)}</small></td><td>${rub(x.price)}</td><td>${num(x.discount)}%</td><td><b>${rub(x.discountedPrice)}</b></td><td><button class="secondary" data-edit-price="${esc(x.nmId)}">РћС‚РєСЂС‹С‚СЊ С‚РѕРІР°СЂ в†’</button></td></tr>`).join('')}</tbody></table>`:'РќРµС‚ С‚РѕРІР°СЂРѕРІ РїРѕ С„РёР»СЊС‚СЂСѓ';$('applyPrices').disabled=true};$('repricerBody').addEventListener('click',e=>{const button=e.target.closest('[data-edit-price]');if(button)openPriceEditor(button.dataset.editPrice)});$('applyPrices').onclick=()=>message('РћС‚РєСЂРѕР№С‚Рµ РєРѕРЅРєСЂРµС‚РЅС‹Р№ С‚РѕРІР°СЂ РІ С‚Р°Р±Р»РёС†Рµ Рё РїСЂРёРјРµРЅРёС‚Рµ С†РµРЅСѓ РІРЅСѓС‚СЂРё РµРіРѕ РєР°СЂС‚РѕС‡РєРё.','info');if($('repricerBrand'))$('repricerBrand').oninput=renderPriceGrid;
$('priceEditorApply').onclick=async()=>{if(!editedPriceProduct)return;const button=$('priceEditorApply'),newPrice=Number($('priceEditorBase').value),discount=Number($('priceEditorDiscount').value),oldPrice=Number(editedPriceProduct.price);button.disabled=true;button.textContent='РћС‚РїСЂР°РІР»СЏРµРјвЂ¦';$('priceEditorStatus').className='price-status';$('priceEditorStatus').textContent='РћС‚РїСЂР°РІР»СЏРµРј РёР·РјРµРЅРµРЅРёРµ РІ WBвЂ¦';try{const response=await fetch('/api/repricer/apply',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:$('repricerToken').value.trim(),confirm:'APPLY',plan:[{nmID:Number(editedPriceProduct.nmId),oldPrice,newPrice,discount,status:'ready'}]})}),data=await response.json();if(!response.ok)throw new Error(data.error||'WB РЅРµ РїСЂРёРЅСЏР» РёР·РјРµРЅРµРЅРёРµ');const uploadID=Number(data.result?.data?.id??data.result?.id);$('priceEditorStatus').textContent=uploadID?`Р—Р°РґР°РЅРёРµ в„–${uploadID} РїСЂРёРЅСЏС‚Рѕ. РџСЂРѕРІРµСЂСЏРµРј СЂРµР·СѓР»СЊС‚Р°С‚вЂ¦`:'WB РїСЂРёРЅСЏР» Р·Р°РїСЂРѕСЃ. РџСЂРѕРІРµСЂСЏРµРј С†РµРЅСѓвЂ¦';let task=null;if(uploadID){for(let attempt=0;attempt<4;attempt++){await new Promise(resolve=>setTimeout(resolve,1500));const statusResponse=await fetch('/api/repricer/status',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:$('repricerToken').value.trim(),uploadID})});task=await statusResponse.json();if(statusResponse.ok&&task.stage==='processed')break}}const item=task?.goods?.find(x=>String(x.nmID)===String(editedPriceProduct.nmId));if(item?.errorText)throw new Error(item.errorText);const refreshedResponse=await fetch('/api/prices',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:$('repricerToken').value.trim(),nmIds:[editedPriceProduct.nmId]})}),refreshed=await refreshedResponse.json();if(!refreshedResponse.ok)throw new Error(refreshed.error||'РќРµ СѓРґР°Р»РѕСЃСЊ РїСЂРѕРІРµСЂРёС‚СЊ РЅРѕРІСѓСЋ С†РµРЅСѓ');const actual=refreshed.prices?.[0];if(actual){Object.assign(editedPriceProduct,actual);$('priceCurrentFinal').textContent=rub(actual.discountedPrice);$('priceCurrentFormula').textContent=`${num(actual.price)} в‚Ѕ в€’ ${num(actual.discount)}%`;renderPriceGrid()}$('priceEditorStatus').className='price-status success';$('priceEditorStatus').textContent=actual&&Number(actual.discount)===discount&&Number(actual.price)===newPrice?'Р“РѕС‚РѕРІРѕ: WB РїРѕРґС‚РІРµСЂРґРёР» РЅРѕРІСѓСЋ С†РµРЅСѓ Рё СЃРєРёРґРєСѓ.':`РР·РјРµРЅРµРЅРёРµ РѕС‚РїСЂР°РІР»РµРЅРѕ. WB РµС‰С‘ РѕР±СЂР°Р±Р°С‚С‹РІР°РµС‚ РµРіРѕ${uploadID?` (Р·Р°РґР°РЅРёРµ в„–${uploadID})`:''}; РѕР±РЅРѕРІР»РµРЅРёРµ РјРѕР¶РµС‚ Р·Р°РЅСЏС‚СЊ РЅРµСЃРєРѕР»СЊРєРѕ РјРёРЅСѓС‚.`}catch(error){$('priceEditorStatus').className='price-status error';$('priceEditorStatus').textContent=error.message}finally{button.disabled=false;button.textContent='РџСЂРёРјРµРЅРёС‚СЊ Рє СЌС‚РѕРјСѓ С‚РѕРІР°СЂСѓ'}};

